def resize_image(
    file, # Image path, relative to `src`
    dest, # Output directory
    src='.', # Directory that `file` is relative to
    max_size=None, # Resize so the larger side is at most this many pixels
    n_channels=3, # Convert to RGB when 3
    ext=None, # Output suffix, e.g. '.png'; default keeps the original
    img_format=None, # PIL format for `save`; default inferred from the suffix
    resample=BILINEAR, # PIL resampling filter
    resume=False, # Skip files already present in `dest`?
    **kwargs # Passed to PIL `Image.save`
):
    "Resize file to dest to max_size"
    dest = Path(dest)
    
    dest_fname = dest/file
    dest_fname.parent.mkdir(exist_ok=True, parents=True)
    file = Path(src)/file
    if resume and dest_fname.exists(): return
    if not verify_image(file): return

    img = Image.open(file)
    imgarr = np.array(img)
    img_channels = 1 if len(imgarr.shape) == 2 else imgarr.shape[2]
    if ext is not None: dest_fname=dest_fname.with_suffix(ext)
    if (max_size is not None and (img.height > max_size or img.width > max_size)) or img_channels != n_channels:
        if max_size is not None:
            new_sz = resize_to(img, max_size)
            img = img.resize(new_sz, resample=resample)
        if n_channels == 3: img = img.convert("RGB")
        img.save(dest_fname, img_format, **kwargs)
    elif file != dest_fname : shutil.copy2(file, dest_fname)

